      "directoryNote": "January 1, 2026 Census geography with complete 2026 GRFC memberships. Cross-county places appear in each intersected county. Statistical CDPs and county subdivisions are separate from incorporated municipal governments. This inventory excludes informal neighborhoods and subsequent boundary changes. Tribal-named CDPs do not represent tribal governments or reservation boundaries. Historical geography-guide counts are superseded by ACS26 tables. Kalawao County is a distinct Census county, dependent on Hawaii state government (G/H4), administered by the Department of Health. It is not Maui County or an independent municipal government. Act 171 (2026), sections 2, 24 and 28, provides a future transfer into Maui County one year after the passing of the last qualifying patient resident, as affirmed by a governor proclamation. This conditional change is not applied to the January 2026 inventory. No incorporated place or CDP is recorded here. The statistical county subdivision is retained separately; informal settlement names are not relabeled as Census places. Hawaii has no Census-recognized incorporated places. Honolulu city and county are governmentally consolidated, but the Census place layer is statistical; Urban Honolulu CDP is not the county or a separate incorporated city.",
